%   Vincentas Gerdvilis
%   Ef-25/1
%   2026-09-10

clear
close all
[X Y] = meshgrid(-2:0.1:1);
f = 1 - 2.*X.^2 - 3.*Y.^2;
figure('Color', '[0 1 0]') %[output:92d72579]
surf(f) %[output:92d72579]
colormap summer %[output:92d72579]
view(70, 70) %[output:92d72579]
xlabel('X') %[output:92d72579]
ylabel('Y') %[output:92d72579]
zlabel('Z') %[output:92d72579]
title('f(x, y) = 1 - 2x^2 - 3y^2') %[output:92d72579]
shading flat %[output:92d72579]
grid on %[output:92d72579]
%%
clear
close all
[X Y] = meshgrid(-2:0.1:2);
f = sin((abs(X + Y))./(20)).*exp(-abs(X + Y));
mesh(f); %[output:64c5dc6b]
shading flat %[output:64c5dc6b]
colormap summer %[output:64c5dc6b]
view(10, 10) %[output:64c5dc6b]
xlabel('X') %[output:64c5dc6b]
ylabel('Y') %[output:64c5dc6b]
zlabel('Z') %[output:64c5dc6b]
title('f(x, y)') %[output:64c5dc6b]
grid on %[output:64c5dc6b]
%%
clear
close all
[X Y] = meshgrid(-2:0.1:2);
z = 1 - (X.^2 + Y.^2);
surf(z) %[output:6b6bfad4]
camlight %[output:6b6bfad4]

